&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Saadet Partisi Genel Başkanı Mahmut Arıkan, TBMM Grup Toplantısı&amp;#39;nda yaptığı konuştu. A&amp;ccedil;ıklanan buğday alım fiyatının &amp;uuml;reticinin maliyetini dahi karşılamadığını belirten Arıkan, &lt;strong&gt;&amp;ldquo;&lt;/strong&gt;Tarım &amp;uuml;lkemiz i&amp;ccedil;in bir milli g&amp;uuml;venlik meselesidir&amp;rdquo; dedi.&amp;nbsp; Pazar g&amp;uuml;n&amp;uuml; 6 beldede ger&amp;ccedil;ekleştirilen ara se&amp;ccedil;im sonu&amp;ccedil;larını ve siyasetin g&amp;uuml;ndemindeki yeni anayasa tartışmalarını değerlendiren Mahmut Arıkan, iktidarın se&amp;ccedil;im stratejisine ve hukuk pratiğine y&amp;ouml;nelik sert eleştiri ve partisinin &amp;ccedil;&amp;ouml;z&amp;uuml;mlerini sıraladı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;AK PARTİ&amp;rsquo;YE&amp;nbsp;OY VERMEYEN&amp;nbsp;VATANDAŞLARIN&amp;nbsp;CUMHURBAŞKANI DEĞİL MİSİNİZ?&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;Malumunuz pazar g&amp;uuml;n&amp;uuml; 6 beldede&amp;nbsp;ara&amp;nbsp;se&amp;ccedil;im yapıldı. &amp;Ouml;ncelikle, sonu&amp;ccedil;ların memleketimize, hayırlar&amp;nbsp;getirmesini temenni ediyorum. Hamdolsun&amp;nbsp;Saadet&amp;nbsp;Partimiz,&amp;nbsp;bu beldelerin en b&amp;uuml;y&amp;uuml;ğ&amp;uuml; olan Mustafapaşa&amp;nbsp;beldesinde&amp;nbsp;%16 oy alarak &amp;uuml;&amp;ccedil;&amp;uuml;nc&amp;uuml; parti olmuştur.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;B&amp;uuml;t&amp;uuml;n adaletsizliklere, b&amp;uuml;t&amp;uuml;n haksız rekabete rağmen, &amp;ouml;nemli bir başarı ortaya&amp;nbsp;koyan, adayımız&amp;nbsp;Doğan Ak beyefendiye, Mustafapaşa teşkilatımıza, se&amp;ccedil;im &amp;ccedil;alışmasında b&amp;uuml;y&amp;uuml;k bir&amp;nbsp;fedak&amp;acirc;rlık&amp;nbsp;ve &amp;ccedil;aba ortaya koyan mensuplarımıza&amp;nbsp;teşekk&amp;uuml;r ediyorum. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bu&amp;nbsp;ara&amp;nbsp;se&amp;ccedil;imde T&amp;uuml;rkiye&amp;#39;nin i&amp;ccedil;inde bulunduğu krizi bir kez daha g&amp;ouml;rd&amp;uuml;k iktidardan tam 6 bakan,&amp;nbsp;tekrar s&amp;ouml;yl&amp;uuml;yorum tam 6 bakan bu beldeye gitti. Devletin&amp;nbsp;ve iktidarın&amp;nbsp;imkanlarını, haksız rekabeti sağlamak i&amp;ccedil;in&amp;nbsp;seferber ettiler...&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Giden bakanlardan biri de Adalet Bakanıydı. Her g&amp;uuml;n&amp;nbsp;yeni&amp;nbsp;bir&amp;nbsp;b&amp;uuml;y&amp;uuml;k&amp;nbsp;dosyanın konuşulduğu,&amp;nbsp;her g&amp;uuml;n&amp;nbsp;yeni&amp;nbsp;bir &amp;ccedil;etenin ortaya &amp;ccedil;ıktığı&amp;nbsp;T&amp;uuml;rkiye&amp;rsquo;de Adalet bakanı, 1.773&amp;nbsp;kişinin oy kullandığı&amp;nbsp;bir beldeye giderek&amp;nbsp;oy istedi.&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Hatırlayacaksınız, bu&amp;nbsp;ucube&amp;nbsp;sisteme ge&amp;ccedil;meden&amp;nbsp;&amp;ouml;nce&amp;nbsp;se&amp;ccedil;imlerde haksız rekabet olmaması i&amp;ccedil;in&amp;nbsp;Adalet Bakanları;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Se&amp;ccedil;ime &amp;uuml;&amp;ccedil; ay kala istifa ederlerdi. Şimdiki&amp;nbsp;sistemde ise Adalet Bakanı&amp;nbsp;kapı kapı gezerek oy istiyor. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ayrıca&amp;nbsp;se&amp;ccedil;im akşamı Sayın Cumhurbaşkanı&amp;rsquo;nın&amp;nbsp;se&amp;ccedil;im akşamı yaptığı&amp;nbsp;a&amp;ccedil;ıklamada kullandığı&amp;nbsp;&amp;quot;ezici&amp;quot; ifadesini şaşkınlıkla&amp;nbsp;takip ettik.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Sayın Cumhurbaşkanım&amp;nbsp;hakikaten&amp;nbsp;merak ediyorum!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Siz,&amp;nbsp;kimi ezdiniz&amp;nbsp;Allah aşkına ya?&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Sizler se&amp;ccedil;imi, muhalefet partilerini&amp;nbsp;bir&amp;nbsp;ezme aracı&amp;nbsp;olarak mı&amp;nbsp;g&amp;ouml;r&amp;uuml;yorsunuz?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;En &amp;ouml;nemlisi siz,&amp;nbsp;pazar g&amp;uuml;n&amp;uuml;&amp;nbsp;Ak Parti&amp;rsquo;ye&amp;nbsp;oy vermeyen&amp;nbsp;vatandaşların&amp;nbsp;Cumhurbaşkanı değil misiniz?&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;İşte biz&amp;nbsp;tam olarak&amp;nbsp;bu sistemle m&amp;uuml;cadele ediyoruz! &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bize her ge&amp;ccedil;en g&amp;uuml;n, daha fazla adaletsizlik, daha fazla istikrarsızlık, daha fazla&amp;nbsp;kriz&amp;nbsp;vaat eden&amp;nbsp;partili&amp;nbsp;cumhurbaşkanlığı h&amp;uuml;k&amp;uuml;met sistemini&amp;nbsp;değiştirmek, rehabilite etmek zorundayız.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bizler&amp;nbsp;bunu aziz milletimize&amp;nbsp;karşı&amp;nbsp;bir vazife olarak g&amp;ouml;r&amp;uuml;yoruz.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;ANAYASA, YENİ D&amp;Ouml;NEMİN SİYASİ KAPISI YAPILMAK İSTENİYOR&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;Mustafapaşa ve sonrasında yaşananlar, T&amp;uuml;rkiye&amp;#39;de devlet aklının, hukuk d&amp;uuml;zeninin ve anayasal sorumluluğun nasıl aşındığını g&amp;ouml;zler &amp;ouml;n&amp;uuml;ne seriyor. İşte tam da b&amp;ouml;yle bir d&amp;ouml;nemde, T&amp;uuml;rkiye, yeniden bir anayasa tartışmasının eşiğine getiriliyor. Elbette! darbe anayasasından kurtulmak &amp;ouml;nemlidir! Fakat; darbe hukukunu, keyf&amp;icirc; y&amp;ouml;netimi, yargı sopasını ve kuvvetler ayrılığını yok sayan anlayışı değiştirmeden yeni anayasa yapmak, eski bir binanın tabelasını değiştirmekten ibaret kalır. &lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Yeni anayasa ihtiyacı doğrudur; fakat bu ihtiyacı bug&amp;uuml;n en &amp;ccedil;ok zayıflatan şey, iktidarın hukuk pratiğidir. Bu anayasa tartışmaları hi&amp;ccedil; ş&amp;uuml;phesiz boşlukta ortaya &amp;ccedil;ıkmış tartışmalar değildir! T&amp;uuml;rkiye&amp;rsquo;de iktidarın yeni bir siyasi hat kurmaya &amp;ccedil;alıştığını g&amp;ouml;r&amp;uuml;yoruz! &lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;İktidar, meseleyi; siyasi alanı yeniden d&amp;uuml;zenleyen, muhalefetin hareket kabiliyetini daraltan, ittifak dengelerini yeniden kuran, toplumu yeni bir g&amp;uuml;venlik dili etrafında hizalamaya &amp;ccedil;alışan bir stratejiyle ele almaktadır. Bu nedenle yeni anayasa başlığı, yalnızca hukuk&amp;ccedil;uların konuşacağı teknik bir başlık değildir. Anayasa, yeni d&amp;ouml;nemin siyasi kapısı yapılmak isteniyor. Biz bu kapının nereye a&amp;ccedil;ıldığını g&amp;ouml;rmek zorundayız.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Eğer bu kapı; hukuka, adalete, &amp;ouml;zg&amp;uuml;rl&amp;uuml;ğe, Meclis&amp;rsquo;in itibarına, milletin birliğine ve devletin ahlakına a&amp;ccedil;ılıyorsa, biz orada en yapıcı tavrı g&amp;ouml;steririz! Ama bu kapı; daha merkeziyet&amp;ccedil;i bir y&amp;ouml;netime, daha denetimsiz bir y&amp;uuml;r&amp;uuml;tmeye, daha bağımlı bir yargıya, daha etkisiz bir Meclis&amp;rsquo;e a&amp;ccedil;ılıyorsa işte biz buna millet adına itiraz ederiz! Onun i&amp;ccedil;in bu meseleye y&amp;uuml;ksek bir dikkatle, b&amp;uuml;y&amp;uuml;k bir sorumlulukla ve devlet ciddiyetiyle bakıyoruz.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;T&amp;Uuml;RKİYE PASAPORTLU SAVAŞ SU&amp;Ccedil;LULARINA KARŞI HAREKETE GE&amp;Ccedil;İN&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;Bu k&amp;uuml;rs&amp;uuml;den bir&amp;ccedil;ok kez ifade ettim. &amp;Uuml;lkemizde sokaklar Teksas&amp;rsquo;a d&amp;ouml;nm&amp;uuml;ş durumda. &amp;Ccedil;eteler şehirlerde cirit atıyor, Her g&amp;uuml;n yeni bir yer kurşunlanıyor...&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;B&amp;ouml;yle bir ortamda Sn. İ&amp;ccedil;işleri Bakanımız en b&amp;uuml;y&amp;uuml;k hayalinin &amp;ldquo;Kud&amp;uuml;s&amp;rsquo;e Vali&amp;rdquo; olmak olduğunu s&amp;ouml;yl&amp;uuml;yor. Tabii, Kendisinin samimi duygularla yaptığını d&amp;uuml;ş&amp;uuml;nd&amp;uuml;ğ&amp;uuml;m&amp;uuml;z bu duaya bizler amin deriz.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Sayın Bakanım madem Kud&amp;uuml;s&amp;rsquo;&amp;uuml; bu kadar &amp;ouml;nemsiyorsunuz; İşe, İ&amp;ccedil;işleri bakanı olarak hem İsrail hem de T&amp;uuml;rkiye Cumhuriyeti vatandaşlığından yararlanan savaş su&amp;ccedil;lularına karşı harekete ge&amp;ccedil;erek başlayabilirsiniz. Bu imk&amp;acirc;ndan yaralananların hepsi, soykırımcı İsrail ordusunda g&amp;ouml;rev yapan isimlerdir. Bu imk&amp;acirc;ndan yararlananların hepsinin, T&amp;uuml;rkiye&amp;rsquo;ye girdikleri anda tutuklanıp, savaş su&amp;ccedil;lusu olarak yargılanması gerekmez mi?&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Bunları tek başıma yapamam diyebilirsiniz! O zaman biz de deriz ki; Ge&amp;ccedil;tiğimiz hafta Adalet Bakanı ile beraber koltuğunuzun altındaki dosya ile Sayın Bah&amp;ccedil;eliyi ziyaret ettiğiniz gibi bir dosyada ak parti grubuna g&amp;ouml;t&amp;uuml;r&amp;uuml;n. O dosyanın i&amp;ccedil;erisinde, bizim daha &amp;ouml;nce 17 Şubat 2026 tarihli meclis araştırma &amp;ouml;nerimiz olsun araştırma &amp;ouml;nerisi burada, hazır. Burada t&amp;uuml;m milletvekili arkadaşlarımızın imzası var.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Sayın i&amp;ccedil;işleri Bakanım, Biz bu &amp;ouml;neriyi getirdik, AK Parti&amp;#39;li milletvekilleri bu &amp;ouml;nerimizi reddetti. Kud&amp;uuml;s&amp;rsquo;e vali olma arzunuz &amp;ouml;nemlidir. Ama bu &amp;ouml;neriyi, AK Parti grubuna kabul ettirmeniz &amp;ccedil;ok daha &amp;ouml;nemlidir.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Siz bunu başarın, bizim sizi destekleyeceğimizden hi&amp;ccedil; ş&amp;uuml;pheniz olmasın. Yeter ki, bu katilleri, bu &amp;uuml;lkede artık barındırmayalım!&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;BASKIN SE&amp;Ccedil;İMİN&amp;nbsp;ALAMETLERİ &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;BİRER BİRER BELİRMEYE BAŞLADI&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;T&amp;uuml;m bu anlattıklarımızdan yola &amp;ccedil;ıkarak karşımıza bir tablo &amp;ccedil;ıkıyor. İktidarın ajandasında &amp;ldquo;Bir baskın se&amp;ccedil;im&amp;rdquo; var. Nerden mi biliyoruz; &amp;ccedil;&amp;uuml;nk&amp;uuml; alametler birer birer belirmeye başladı.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Birinci alamet: Anayasa Tartışmaları. İkinci alamet: Muhalefete Yapılan Operasyonlar. &amp;Uuml;&amp;ccedil;&amp;uuml;nc&amp;uuml; alamet: YSK&amp;#39;daki Hareketlilik. D&amp;ouml;rd&amp;uuml;nc&amp;uuml; alamet: Varlık Barışı. Beşinci alamet: ABD Swap Hattı. &lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Geriye iki şey kaldı; Gabar&amp;#39;da petrol, Karadeniz&amp;#39;de doğal gaz m&amp;uuml;jdesi kaldı. O alametlerde pek yakında duyurulacaktır.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Buradan, bir kez daha a&amp;ccedil;ık&amp;ccedil;a s&amp;ouml;yl&amp;uuml;yoruz; İktidarın ajandası ne olursa olsun Biz; Baskın se&amp;ccedil;ime de Erken se&amp;ccedil;ime de Yerel se&amp;ccedil;ime de Genel se&amp;ccedil;ime de hazırız. Milletimizin hakkını, hukukunu, beklentisini, umudunu savunacağız! Kimsenin ş&amp;uuml;phesi olmasın! Bu millete, oh be dedirteceğiz!&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;İKTİDAR; KUMARLA M&amp;Uuml;CADELE ETMİYOR!&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;Mustafapaşa ve sonrasında yaşananlar, T&amp;uuml;rkiye&amp;rsquo;de devlet aklının hukuk d&amp;uuml;zeninin ve anayasal sorumluluğun nasıl aşındığını g&amp;ouml;zler &amp;ouml;n&amp;uuml;ne seriyor. İşte tam da b&amp;ouml;yle bir d&amp;ouml;nemde, T&amp;uuml;rkiye, yeniden bir anayasa tartışmasının eşiğine getiriliyor. Elbette! Darbe anayasasından kurtulmak &amp;ouml;nemlidir! Fakat; darbe hukukunu, keyf&amp;icirc; y&amp;ouml;netimi, yargı sopasını ve kuvvetler ayrılığını yok sayan anlayışı değiştirmeden yeni anayasa yapmak, eski bir binanın tabelasını değiştirmekten ibaret kalır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Bu kadar yoğun g&amp;uuml;ndemin arasında, milletimizin g&amp;uuml;ndeminin g&amp;ouml;lgede kalmasını istemiyoruz. Hepimizin malumu, Son yıllarda en b&amp;uuml;y&amp;uuml;k toplumsal sorunlarından biri, kumar ve uyuşturucu bağımlılığının giderek yaygınlaşmasıdır. Bu k&amp;uuml;rs&amp;uuml;den Sayın Babacan da Sayın Davutoğlu da biz de bu konuya defalarca dikkat &amp;ccedil;ektik. Kumarın da uyuşturucunun da aileleri dağıttığını, Gen&amp;ccedil;leri karanlığa s&amp;uuml;r&amp;uuml;klediğini, Toplumu i&amp;ccedil;ten i&amp;ccedil;e &amp;ccedil;&amp;uuml;r&amp;uuml;tt&amp;uuml;ğ&amp;uuml;n&amp;uuml; s&amp;ouml;yledik. Ancak iktidar bu &amp;ccedil;ağrılarımıza kulak vermedi!&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Şimdi de torba yasa i&amp;ccedil;erisine koydukları bir d&amp;uuml;zenlemeyle, Sanki soruna &amp;ccedil;&amp;ouml;z&amp;uuml;m &amp;uuml;retiyormuş gibi davranıyorlar. Neymiş -efendim-; &amp;ldquo;Bahis şirketlerinin reklam giderleri artık vergi matrahından d&amp;uuml;ş&amp;uuml;lemeyecekmiş.&amp;rdquo; Yapmayın ya! Buradan h&amp;uuml;k&amp;uuml;meti vatandaşımıza şik&amp;acirc;yet ediyorum.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;İktidar; Kumarla m&amp;uuml;cadele etmiyor! M&amp;uuml;cadele ediyormuş gibi yapıp, kumardan alınacak verginin hesabı yapılıyor. İktidar şunu s&amp;ouml;yl&amp;uuml;yor: &amp;ldquo;Vergisini verdiğin s&amp;uuml;rece kumar ile benim meselem yok&amp;rdquo; diyor.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;İktidar yetkililerine sesleniyorum; Vergilendirilmiş kumar da haramdır. Vergisiz kumar da haramdır. Yasal kumar da zehirdir. Yasadışı kumar da zehirdir. Engel olmadığınız kumarın topluma verdiği zarar, devletin kasasına giren vergiden &amp;ccedil;ok daha b&amp;uuml;y&amp;uuml;kt&amp;uuml;r. Bir gencin kaybolan geleceğinin, Bir annenin d&amp;ouml;kt&amp;uuml;ğ&amp;uuml; g&amp;ouml;zyaşının vergisi olmaz&lt;strong&gt;.&lt;/strong&gt; Aziz milletimiz sizden kumara yeni vergi kalemleri &amp;uuml;retmenizi beklemiyor&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;strong&gt;&amp;ldquo;TARIM &amp;Uuml;LKEMİZ İ&amp;Ccedil;İN BİR MİLLİ G&amp;Uuml;VENLİK MESELESİDİR&amp;rdquo;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;strong&gt;&amp;ldquo;&lt;/strong&gt;Bir tarafta; toplumumuzu i&amp;ccedil;ten i&amp;ccedil;e &amp;ccedil;&amp;uuml;r&amp;uuml;ten kumar d&amp;uuml;zeni var. Diğer tarafta ise bu milletin &amp;uuml;retimini ve geleceğini ayakta tutan &amp;ccedil;ift&amp;ccedil;imizin alın teri var.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Ne hazin ki AK Parti iktidarı; kumarda verginin hesabını ince ince yaparken, &amp;Ccedil;ift&amp;ccedil;imizin maliyetini g&amp;ouml;rmezden geliyor. Malumunuz, Ge&amp;ccedil;tiğimiz hafta buğday ve arpa alım fiyatları a&amp;ccedil;ıklandı. A&amp;ccedil;ıklanan fiyat Ne &amp;ccedil;ift&amp;ccedil;inin y&amp;uuml;z&amp;uuml;n&amp;uuml; g&amp;uuml;ld&amp;uuml;r&amp;uuml;r ne toprağın hakkını ne de alın terinin hakkını verir.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;TMO diyor ki kilo başına, 16 lira 50 kuruş! Biz de Tarım Politikaları Kurulumuzla birlikte &amp;ccedil;alıştık. Başlık başlık, kalem kalem, rakam rakam hesapladık. Burada uzun uzun detaya girmeyeceğim. Ama milletimiz bilsin diye s&amp;ouml;yl&amp;uuml;yorum: Bakınız; Dekarda verim, 300 KG olursa, Kira, Tarla Hazırlığı ve Ekiliş maliyeti, 2.400 lira Bakım maliyeti &amp;ndash; 905 lira Amortisman maliyeti &amp;ndash; 1600 lira Hasat &amp;ndash; Harman maliyeti &amp;ndash; 480 lira İş&amp;ccedil;ilik &amp;ndash; 800 lira Faiz &amp;ndash; 1.650 lira Toplam 7.830 lira ediyor.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Temel destek ve tohum kullanım desteği &amp;ccedil;ıktığında, 1 kilo buğdayın maliyeti, yaklaşık 24 liraya tekab&amp;uuml;l ediyor. Tarım-&amp;Uuml;FE&amp;#39;si y&amp;uuml;zde 42 seviyesinde a&amp;ccedil;ıklandı. Peki; h&amp;uuml;k&amp;uuml;met ne kadar artış yaptı? Y&amp;uuml;zde 21 Yani maliyet başka yere gitmiş, fiyat artışı başka yerde kalmış. &amp;Ccedil;ift&amp;ccedil;i bu fiyatla kilo başına yaklaşık 7 lira zarar ediyor. Bu arada eğer devlet, buğday alımını 24 lira a&amp;ccedil;ıklarsa &amp;ccedil;ift&amp;ccedil;i ancak maliyetini karşılayabilecek.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Değerli arkadaşlar, bu iş b&amp;ouml;yle devam etmez. Nasıl &amp;ldquo;Savunma Sanayii&amp;rdquo; milli g&amp;uuml;venlik meselesiyse Tarım da &amp;uuml;lkemiz i&amp;ccedil;in bir milli g&amp;uuml;venlik meselesidir.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;&amp;Ccedil;İFT&amp;Ccedil;İYİ MASA BAŞINDA DEĞİL, TARLANIN BAŞINDA DİNLEYECEKSİNİZ!&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;Peki, bu iş nasıl &amp;ccedil;&amp;ouml;z&amp;uuml;lecek? &amp;Ouml;ncelikle, bu iş, fiyatlar nedeniyle hakkını arayan &amp;ccedil;ift&amp;ccedil;ilere ceza keserek &amp;ccedil;&amp;ouml;z&amp;uuml;lmez!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Trakt&amp;ouml;rlerle eylem yaptın diye &amp;ccedil;ift&amp;ccedil;ilere ceza kesildi! Eylem yapan &amp;ccedil;ift&amp;ccedil;iler susturulmaya &amp;ccedil;alışıldı! Siz bu rakamları a&amp;ccedil;ıklayarak, &amp;ccedil;ift&amp;ccedil;iye en b&amp;uuml;y&amp;uuml;k cezayı kestiniz zaten! &amp;Uuml;st&amp;uuml;ne bir de ceza kesmek hangi aklın &amp;uuml;r&amp;uuml;n&amp;uuml; Allah aşkına! Peki &amp;ccedil;ift&amp;ccedil;imizin derdine derman olmak i&amp;ccedil;in ne yapılacak?&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Bir! &amp;Ouml;nce &amp;ccedil;ift&amp;ccedil;iyi masa başında değil, tarlanın başında dinleyeceksiniz! Bunu yaparsanız, kimsenin sokaklara d&amp;ouml;k&amp;uuml;lmesine gerek kalmaz.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;İki, Buğday alım fiyatını hasat zamanı değil, ekimden &amp;ouml;nce a&amp;ccedil;ıklayacaksınız. Biz, Fiyatı y&amp;uuml;kseltin demiyoruz. Doğru d&amp;uuml;r&amp;uuml;st bir planlama yapın, maliyetleri geri &amp;ccedil;ekin diyoruz!&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;Uuml;&amp;ccedil;, &amp;Ccedil;ift&amp;ccedil;iye k&amp;acirc;r payı bırakılacak. &amp;Ccedil;ift&amp;ccedil;i topraktan vazge&amp;ccedil;irilmeyecek.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;D&amp;ouml;rt; TMO &amp;uuml;r&amp;uuml;n bedelini 45 g&amp;uuml;n sonra değil, teslimde &amp;ouml;deyecek. &amp;Ccedil;ift&amp;ccedil;i esnafın vicdanına terk edilmeyecek! Şunu da s&amp;ouml;yleyelim, TMO, Et-S&amp;uuml;t Kurumu ve &amp;Ccedil;AYKUR birer satın alma kurumu değildir. Bu kurumlar piyasayı d&amp;uuml;zenlemek, &amp;Uuml;reticiyi korumak ve arz g&amp;uuml;venliğini sağlamak i&amp;ccedil;in vardır. Eğer bu kurumlar &amp;quot;satın almacı&amp;quot; gibi devam ederse, Piyasayı d&amp;uuml;zenleyen t&amp;uuml;m mekanizmaları kaybederiz.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Biz, Buğday &amp;uuml;reticimizin yanındayız. Arpa &amp;uuml;reticimizin yanındayız. Anadolu&amp;#39;daki t&amp;uuml;m &amp;ccedil;ift&amp;ccedil;ilerimizin yanındayız. Bug&amp;uuml;n aramızda &amp;ccedil;ift&amp;ccedil;ilerimiz var. Onları dinledik. &amp;Ccedil;alışmalarımız hazır. Bug&amp;uuml;n de meclis araştırma &amp;ouml;nerisi vereceğiz.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Gelin bug&amp;uuml;n mecliste vereceğimiz &amp;ouml;nerimize yok demeyin, &amp;Ccedil;ift&amp;ccedil;imizin derdini, Buğdayı, arpayı, tarım politikalarınızı konuşalım. &amp;Ccedil;&amp;ouml;z&amp;uuml;m arayalım!&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;a name=&quot;_Toc231946279&quot;&gt;&lt;/a&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;B&amp;Uuml;Y&amp;Uuml;MEDEN KİMİN HABERİ VAR?&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;T&amp;uuml;m bunlardan sonra bize diyorlar ki; &amp;ldquo;%2,5 b&amp;uuml;y&amp;uuml;d&amp;uuml;k, Kişi başına neredeyse 50 bin dolarlık bir alım g&amp;uuml;c&amp;uuml; var&amp;rdquo; Peki buğday &amp;uuml;reticisinin, &amp;ccedil;ift&amp;ccedil;inin bundan niye haberi yok? Asgari &amp;uuml;cretlinin, emeklinin bundan niye haberi yok?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Kimin haberi var biliyor musunuz? Bankaların, faizci d&amp;uuml;zenin komiserlerinin, haberi var! Bankacılık sekt&amp;ouml;r&amp;uuml; 2026&amp;#39;nın ilk d&amp;ouml;rt ayında 364 milyar liradan fazla net k&amp;acirc;r elde etmiş. Toplam aktif b&amp;uuml;y&amp;uuml;kl&amp;uuml;k 50 trilyon lirayı aşmış durumda.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;U&amp;ccedil;ulmayan havalimanından, para kazananların haberi var! Kur Korumalı Mevduatla ceplerini dolduranların haberi var!&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;strong&gt;&amp;ldquo;NE ZAMAN SANDIKTA KAYBETME KORKUSU YAŞADILAR, O ZAMAN GERİ ADIM ATTILAR&amp;rdquo;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;Bug&amp;uuml;n bu k&amp;uuml;rs&amp;uuml;den &amp;ccedil;ok a&amp;ccedil;ık bir ger&amp;ccedil;eği ifade etmek istiyorum. İktidarın tek bir korkusu var: milletin desteğini kaybetmek. Tek bir endişesi var: sandıkta bedel &amp;ouml;demek. Tek bir hassasiyeti var: oy kaybetmek. Bakın, yıllardır bunu g&amp;ouml;rd&amp;uuml;k... Milletin kararlılığını g&amp;ouml;r&amp;uuml;nce; Yapmayız dedikleri ne varsa yaptılar. Vermeyiz dedikleri ne varsa verdiler. Atmayız dedikleri t&amp;uuml;m adımları attılar. &amp;Ccedil;&amp;uuml;nk&amp;uuml; karşılarında oy kaybetme ihtimalini g&amp;ouml;rd&amp;uuml;ler.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Demek ki mesele imk&amp;acirc;n değilmiş. Demek ki mesele kaynak değilmiş. Demek ki mesele &amp;ccedil;&amp;ouml;z&amp;uuml;m &amp;uuml;retmek değilmiş. Mesele, sadece siyasi maliyet hesaplarıymış. Ne zaman oylarının azaldığını hissettiler, o zaman milletin sesini duydular. Ne zaman sandıkta kaybetme korkusu yaşadılar, o zaman geri adım attılar.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Şimdi de ustalık d&amp;ouml;nemlerini sergiliyorlar. Neyin ustalığı? Milletin g&amp;ouml;z&amp;uuml;n&amp;uuml; boyamanın! Ger&amp;ccedil;ek sorunları g&amp;uuml;ndemden ka&amp;ccedil;ırmanın! Sorumluluğu başkalarına y&amp;uuml;klemenin! Milletimizden s&amp;uuml;rekli sabır istemenin! Ustalığını sergiliyorlar. Yıllardır milletimizin g&amp;ouml;z&amp;uuml;n&amp;uuml; &amp;ouml;yle bir maharetle boyadılar ki, vatandaşımız her defasında sandıkta Ak Parti&amp;rsquo;ye vermesi gereken cezayı erteledi.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Bu ertelemeden dolayı; emeklilerin a&amp;ccedil;lık sınırının altında yaşamasına aldırış etmiyorlar. Bu ertelemeden dolayı; asgari &amp;uuml;cretlinin ay sonunu nasıl getireceğini d&amp;uuml;ş&amp;uuml;nm&amp;uuml;yorlar. Bu ertelemeden dolayı; &amp;ccedil;ift&amp;ccedil;inin bor&amp;ccedil; i&amp;ccedil;inde &amp;uuml;retim yapmaya &amp;ccedil;alışmasını g&amp;ouml;rmezden geliyorlar. Bu ertelemeden dolayı; enflasyon asla d&amp;uuml;şmeyecek, faiz asla d&amp;uuml;şmeyecek. Bu ertelemeden dolayı; Adalet ahlak liyakat denince dudak b&amp;uuml;k&amp;uuml;yorlar! Bu ertelemeden dolayı; yolsuzluk, israf, torpil t&amp;uuml;m devleti kuşatmış durumda!&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;a name=&quot;_Toc231946281&quot;&gt;&lt;/a&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;T&amp;Uuml;RKİYE&amp;#39;NİN D&amp;Ouml;RT BİR YANINA DAVETTE BULUNUYORUZ&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;Bu sefer; milletimizin g&amp;ouml;z&amp;uuml;n&amp;uuml;n boyanmasına izin vermeyeceğiz. Bizi g&amp;ouml;r&amp;uuml;nmez kılmak isteyenlere karşı Israrla her ortamda g&amp;ouml;r&amp;uuml;neceğiz! milletimizin haklı itirazını, haklı &amp;ouml;fkesini ve haklı taleplerini siyaset sahnesine durmaksızın taşıyacağız! ger&amp;ccedil;eklerin unutturulmasına izin vermeyeceğiz. &amp;Ccedil;&amp;uuml;nk&amp;uuml; biz kendi siyasetimize g&amp;ouml;re bir millet istemiyoruz, siyaseti bizatihi milletimiz i&amp;ccedil;in yapıyoruz. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Bug&amp;uuml;n, buradan, T&amp;uuml;rkiye&amp;#39;nin d&amp;ouml;rt bir yanına davette bulunuyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;İktidara g&amp;uuml;&amp;ccedil;l&amp;uuml; bir itirazda bulunmak isteyen herkesi, israfa ve adaletsizliğe karşı durmak isteyen herkesi, Adalet, liyakat ve ehliyet l&amp;uuml;tuf değil hakkımızdır diyen herkesi, Evlenemeyen, iş bulamayan, eğitim imkanından dahi mahrum kalmış, okuduğu halde masraflarını karşılayamayan t&amp;uuml;m gen&amp;ccedil;lerimizi, T&amp;uuml;rkiye&amp;#39;nin yanlış y&amp;ouml;netildiğini d&amp;uuml;ş&amp;uuml;nen herkesi, İktidarın uygulamalarına demokratik yollardan artık yeter demek isteyen herkesi, aramıza davet ediyor, d&amp;uuml;n&amp;uuml; bug&amp;uuml;n&amp;uuml; ve geleceği temiz bu kutlu hareketin bayrağı altında buluşmaya &amp;ccedil;ağırıyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Bu &amp;uuml;lkede hi&amp;ccedil;bir iktidar, milletin iradesinden daha g&amp;uuml;&amp;ccedil;l&amp;uuml; değildir. Hi&amp;ccedil;bir propaganda, ger&amp;ccedil;eği sonsuza kadar &amp;ouml;rtemez. Hi&amp;ccedil;bir algı milletin vicdanını sonsuza kadar susturamaz. G&amp;uuml;n gelir, millet kararını verir. Ve o kararın &amp;ouml;n&amp;uuml;nde hi&amp;ccedil;bir g&amp;uuml;&amp;ccedil; duramaz.&lt;span style=&quot;color:black&quot;&gt;&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
